/** Extract inner message based on type. */
export function extractInner(message: ProtocolMessage): any {
  const extension = EXTENSION_LOOKUP.get(message.type);
  if (extension) return (message as any)[extension];
  throw new Error("unknown type: " + String(message.type));
}
